/* רקיע — טקסטי אספקטים, חלק שני: ונוס ומאדים מול הפלנטות שאחריהן, עשרת
   הזוגות של הפלנטות האיטיות, וארבעת היסודות. קובץ נתונים בלבד. */
RAKIA.TEXTS.aspect["venus-mars"] = RAKIA.TEXTS.aspect["venus-mars"] || {};
RAKIA.TEXTS.aspect["venus-mars"].conjunction = T("צמידות בין ונוס למאדים ממזגת רצון עם משיכה. יש כאן חום, יוזמה בקשר ויכולת לומר בקול מה נעים ומה לא. למשל, בערב עם חברים מי שנושא את זה הוא הראשון שמציע לצאת לרקוד, ומושך אחריו את כולם. האתגר הוא שהדחף מקדים את ההקשבה, והמילה יוצאת לפני שהאחר סיים לדבר. מה שעוזר הוא רגע קטן של השהיה לפני שפועלים, נשימה אחת. החום הזה יפה כשיש לו גם אוזן.");
RAKIA.TEXTS.aspect["venus-mars"].sextile = T("שישית בין ונוס למאדים פותחת דלת בין הנאה לפעולה. ההזדמנות היא לשלב חן עם אומץ, אך היא אינה נכנסת לבד. למשל, בטיול קבוצתי מישהו רואה אדם שמעניין אותו, ובמקום לחכות פשוט ניגש ושואל מאיפה הוא מכיר את המסלול. מי שיוזם, מזמין ומתחיל שיחה מקבל את הטוב שבשילוב. הצד המאתגר הוא שנוח לחכות שהאחר יתחיל, ואז הפתח נסגר בשקט. עוזר להחליט מראש על צעד קטן אחד בכל מפגש. הדלת פתוחה, וצריך רק לעבור בה.");
RAKIA.TEXTS.aspect["venus-mars"].square = T("ריבוע בין ונוס למאדים יוצר חיכוך בין מה שרוצים למה שנעים. הכוח הוא תשוקה שאינה נרדמת, והאתגר הוא ויכוחים שנולדים מקוצר רוח. למשל, בארוחת ערב זוגית שיחה קלה על תוכנית לשבת הופכת בתוך דקה לוויכוח על מי מחליט. אחר כך שני הצדדים לא זוכרים על מה זה התחיל. עוזר לזכור שרכות ורצון אינם אויבים, ולומר קודם מה רוצים ורק אחר כך למה. החיכוך הזה הוא גם מה ששומר על הקשר ער.");
RAKIA.TEXTS.aspect["venus-mars"].trine = T("משולש בין ונוס למאדים מזרים בקלות בין משיכה למעשה. יש כאן חן טבעי וקלות בקשר, ואנשים נמשכים בלי שצריך להתאמץ. למשל, בעבודה בצוות מי שנושא את זה מצליח לבקש עזרה בחיוך ולקבל אותה, בלי שאיש מרגיש שנדרש ממנו משהו. הצד השני הוא שקלות מרדימה, ומה שנוח אינו נבדק. קשר שבא בקלות עלול להישאר שטחי, כי לא היה צריך לעבוד עליו. עוזר לבחור בכוונה, ולא רק ללכת עם הזרם. הקלות היא מתנה, והכוונה היא מה שמשאיר אותה.");
RAKIA.TEXTS.aspect["venus-mars"].opposition = T("ניגוד בין ונוס למאדים מותח חבל בין ריצוי לבין דרישה. פעם אחת נותנים יותר מדי, ופעם אחרת דורשים יותר מדי. למשל, בבחירת מסעדה מוותרים שלוש פעמים ברצף על מה שבא, ובפעם הרביעית מתפרצים על עניין קטן. הצד שמאתגר הוא שהאחר אינו מבין מאיפה זה בא, כי הוויתור היה שקט. האיזון נמצא כשמותר גם לרצות וגם להתחשב באותו רגע. עוזר לומר מוקדם, בקול נעים, מה רוצים. כך החבל נשאר מתוח בנעימות ולא נקרע.");

RAKIA.TEXTS.aspect["venus-jupiter"] = RAKIA.TEXTS.aspect["venus-jupiter"] || {};
RAKIA.TEXTS.aspect["venus-jupiter"].conjunction = T("כשונוס ויופיטר בצמידות, האהבה והנדיבות נמזגות לחום גדול. יש כאן לב פתוח, אופטימיות בקשר והנאה מיופי ומאנשים. למשל, אורח שנכנס לבית מקבל שולחן מלא, חיבוק ושיחה ארוכה, גם אם בא רק להחזיר ספר. האתגר הוא הגזמה, במתנות ובציפיות, ולפעמים גם אכזבה כשהאחר אינו משיב באותה מידה. מה שמאזן הוא מידה: לתת קצת פחות ולהיות נוכח קצת יותר. הלב הרחב הזה מחמם חדר שלם, וטוב לו כשמישהו שומר גם עליו.");
RAKIA.TEXTS.aspect["venus-jupiter"].sextile = T("יש כאן שישית בין ונוס ליופיטר, הזדמנות לצמוח דרך קשרים ודרך יופי. הפתח קיים, אך צריך לעבור בו: להזמין, להודות, להרחיב מעגל. למשל, בקורס חדש מי שנושא את זה יכול להציע לקבוצה קטנה ללמוד יחד, ומשם נולדות חברויות שנשארות. בלי יוזמה החן נשאר בגדר אפשרות, נעים בלי שיוצא ממנו דבר. הצד המאתגר הוא נטייה להסתפק בחיוך ולא להמשיך הלאה. עוזר לקבוע מעשה אחד קטן אחרי כל מפגש טוב. הזדמנות שנענים לה פורחת.");
RAKIA.TEXTS.aspect["venus-jupiter"].square = T("ריבוע בין ונוס ליופיטר מייצר חיכוך בין רצון להנאה לבין רצון ליותר. הכוח הוא לב רחב, והאתגר הוא לא לדעת מתי די. למשל, בקניות לחג העגלה מתמלאת בדברים יפים שאיש לא ביקש, ובבית מגלים שאין מקום לכולם. גם בקשר יש נטייה להבטיח יותר ממה שאפשר להחזיק. מה שעוזר הוא לבחור פחות ולהעריך יותר, ולשאול לפני כל תוספת אם היא באמת חסרה. הנדיבות כאן אמיתית, וכשהיא מקבלת גבול היא נעשית מדויקת.");
RAKIA.TEXTS.aspect["venus-jupiter"].trine = T("משולש בין ונוס ליופיטר זורם בנועם: קל לחבב ולהיות אהוב, קל למצוא טוב. למשל, בפגישה ראשונה עם המשפחה של בן זוג כולם מרגישים בנוח תוך רבע שעה, כאילו הכירו שנים. הזרימה הזאת עלולה להירדם לנוחות שאינה דורשת מאמץ. הצד המאתגר הוא שקשר שבא בקלות לא מקבל את הטיפול שמגיע לו, כי נדמה שהוא מסתדר לבד. עוזר להכניס גם עשייה מכוונת אל הטוב, כמו הודעה יזומה או ערב שמתכננים מראש. החן הזה נשאר טרי כשמשקים אותו.");
RAKIA.TEXTS.aspect["venus-jupiter"].opposition = T("ניגוד בין ונוס ליופיטר מותח בין קרבה לבין מרחב. מצד אחד רצון בקשר קרוב, ומצד שני צורך בחופש ובהרחבה. למשל, אחרי שבוע צמוד ונעים עם בן זוג מגיע פתאום רצון לנסוע לבד לכמה ימים, והאחר נפגע בלי להבין. הצד המאתגר הוא שהמעבר בין שני הצרכים נעשה בקפיצה ולא בהסבר. האיזון נבנה כשמכירים בשני הצרכים במקום לבחור צד. עוזר לומר מראש שיש צורך במרחב, ושהוא אינו נגד הקשר. שניהם אמיתיים, ויש להם מקום.");

RAKIA.TEXTS.aspect["venus-saturn"] = RAKIA.TEXTS.aspect["venus-saturn"] || {};
RAKIA.TEXTS.aspect["venus-saturn"].conjunction = T("צמידות בין ונוס לסטורן ממזגת אהבה עם אחריות. הכוח כאן הוא נאמנות ומחויבות שאינה נשברת מהר, והאתגר הוא קושי להראות רגש וספק אם מגיע. למשל, ביום הולדת של אדם קרוב מי שנושא את זה מכין הכול בדיוק, אך שוכח לומר בקול כמה הוא אוהב. הרגש קיים ועמוק, רק הביטוי שלו מהוסס. עוזר לתת לחום לצאת גם בלי הצדקה, במילה אחת פשוטה או ביד על הכתף. אהבה שנבנית לאט מחזיקה הרבה, וטוב לה כשהיא גם נאמרת.");
RAKIA.TEXTS.aspect["venus-saturn"].sextile = T("שישית בין ונוס לסטורן מציעה הזדמנות לבנות קשר שיש לו יסודות. הכוח הוא סבלנות ורצינות באהבה. למשל, חברות שמתחילה בשיחת מסדרון קצרה יכולה להפוך למפגש קבוע פעם בשבוע, ומהקביעות הזאת נולד אמון. ההזדמנות הזאת מבקשת מעשה קטן וקבוע, כי קרבה כאן נבנית בצעדים ולא בקפיצה. הצד המאתגר הוא שקל לדחות את הצעד למועד נוח יותר, שאינו מגיע. עוזר לקבוע יום ושעה ולעמוד בהם. מה שנבנה כך נשאר.");
RAKIA.TEXTS.aspect["venus-saturn"].square = T("ריבוע בין ונוס לסטורן מפגיש רצון בקרבה עם חשש מדחייה. החיכוך מלמד לאהוב במידה ובאמת, אך הוא גם סוגר את הלב לפעמים. למשל, הודעה חמה שנשלחה ולא נענתה במשך שעה מתפרשת מיד כסימן שלא רוצים, ומי שנושא את זה מתכנס ומפסיק לכתוב. בפועל האחר היה בנהיגה. הצד השני הוא שהזהירות הזאת שומרת מפני קשרים ריקים. מה שעוזר הוא לתת לרכות מקום לפני הביקורת, ולשאול לפני שמסיקים. הלב כאן זהיר, וגם הוא רוצה להיפתח.");
RAKIA.TEXTS.aspect["venus-saturn"].trine = T("משולש בין ונוס לסטורן מזרים יציבות אל תוך הקשר. יש כאן טעם פשוט, נאמנות וקצב שקט. למשל, זוג שיושב שנים באותו בית קפה, באותו שולחן, ומרגיש שם בבית יותר מבכל מקום חדש. הזרימה הזאת עלולה להפוך לשגרה שאינה נבדקת, וכל ערב נראה כמו הערב שלפניו. הצד המאתגר הוא שקט שמתחפש לשביעות רצון. עוזר להזמין מדי פעם משהו חדש, מסלול אחר או שיחה על דבר שלא דיברו עליו. היציבות היא בית, וגם בבית פותחים חלון.");
RAKIA.TEXTS.aspect["venus-saturn"].opposition = T("ניגוד בין ונוס לסטורן מותח בין צורך בחום לבין צורך בגבול. הקוטב האחד מבקש קרבה, והשני שומר מרחק. למשל, בסוף יום עבודה מישהו רוצה חיבוק ושיחה, והאחר מבקש חצי שעה לבד, ושניהם מרגישים דחויים. הצד המאתגר הוא שכל צד קורא את הצורך של השני כדחייה. האיזון נמצא כשמבינים שגבול ברור הוא גם צורה של אכפתיות. עוזר לומר בקול מה הצורך ומתי, במקום להסיק. כך החום והגבול חיים באותו בית.");

RAKIA.TEXTS.aspect["venus-uranus"] = RAKIA.TEXTS.aspect["venus-uranus"] || {};
