RAKIA.TEXTS.aspect["venus-uranus"].square = T("ריבוע בין ונוס לאורנוס יוצר חיכוך בין רצון בקרבה לבין רצון בחופש. הכוח הוא מקוריות, והאתגר הוא ניתוקים פתאומיים כשמרגישים חנק. למשל, אחרי ערב נעים בן הזוג שואל מה התוכנית למחר, ומי שנושא את זה מרגיש פתאום כלוא ומתקרר בלי הסבר. האחר נשאר מבולבל, כי לפני רגע היה טוב. עוזר לומר בקול מה הצורך לפני שעוזבים: צריך אוויר, לא צריך להיעלם. הצורך בחופש אמיתי, ואפשר להגיד אותו במילים במקום בדלת.");
RAKIA.TEXTS.aspect["venus-uranus"].trine = T("משולש בין ונוס לאורנוס נותן קלות במפגש עם אנשים שונים וטעם מקורי. למשל, במסיבה מי שנושא את זה עובר בקלות בין קבוצות, צוחק עם כולם ולובש משהו שאיש לא היה מעז. הזרימה נעימה, אך היא עלולה להישאר על פני השטח. הצד המאתגר הוא שהרבה היכרויות אינן הופכות לקשר אחד קרוב, כי בכל פעם יש מישהו חדש. עוזר לתת לקשר אחד להעמיק, ולא רק לקפוץ בין חידושים. הפתיחות יפה, והעומק הוא מה שנותן לה משמעות.");
