RAKIA.TEXTS.aspect["venus-neptune"].square = T("ריבוע בין ונוס לנפטון מייצר חיכוך בין כמיהה לבין מציאות. הכוח הוא לב רחב ודמיון, והאתגר הוא אכזבה כשאדם אינו האידיאל שדמיינו. למשל, חבר חדש מספר על עצמו בהתלהבות, ומי שנושא את זה משלים בראש את כל מה שלא נאמר, לטובה. כמה שבועות אחר כך מתברר שהאדם פשוט אחר, לא רע, רק אחר. עוזר לשאול שאלות פשוטות לפני שמתמסרים, ולהניח למציאות להיות פחות יפה מהחלום. הלב הזה יודע לאהוב, ומגיע לו לאהוב אדם אמיתי.");
RAKIA.TEXTS.aspect["venus-neptune"].trine = T("משולש בין ונוס לנפטון מזרים חן רך, אמפתיה וחוש ליופי. למשל, בשיחת ערב מישהו מתחיל לספר על קושי, ומי שנושא את זה מבין הכול עוד לפני שהמילים נגמרו, ומרגיע רק בנוכחות. הזרימה קלה כל כך שקל להיסחף ולשכוח לבדוק. הצד המאתגר הוא נטייה להאמין לכל סיפור יפה ולתת בלי גבול. מה שמאזן הוא רגל אחת על הקרקע גם כשהלב מרחף: לבדוק פרט אחד, לשאול שאלה אחת. החמלה כאן מתנה, ויש לה ערך רב כשהיא גם רואה.");
RAKIA.TEXTS.aspect["venus-neptune"].opposition = T("ניגוד בין ונוס לנפטון מותח בין רצון בקשר אמיתי לבין געגוע לקשר מושלם. הקוטב האחד מבקש אדם, והשני מבקש חלום. למשל, בן זוג נעים ואמין נראה פתאום אפור ליד דמות מסרט, ומתחיל געגוע למשהו שלא קיים. הצד המאתגר הוא שהאדם שלידנו מקבל פחות ממה שמגיע לו, בגלל השוואה שאינה הוגנת. האיזון נמצא כשמותר לאהוב גם את מה שאינו מושלם. עוזר לשים לב לרגע אחד טוב ביום עם האדם האמיתי. החלום יכול להישאר בסרט.");

RAKIA.TEXTS.aspect["venus-pluto"] = RAKIA.TEXTS.aspect["venus-pluto"] || {};
