RAKIA.TEXTS.aspect["venus-pluto"].sextile = T("שישית בין ונוס לפלוטו פותחת דלת לקשר שמשנה מבפנים. ההזדמנות מבקשת אומץ להיחשף ולומר את מה שמפחיד. למשל, בשיחת לילה עם חבר ותיק מישהו מספר לראשונה על דבר שהסתיר שנים, ומגלה שהקשר נעשה קרוב פי כמה. מי שמעז לדבר על מה שמתחת לפני השטח מגלה קרבה אחרת. הצד המאתגר הוא שנוח לשמור את העומק לעצמו ולהישאר בשיחות קלות. עוזר לבחור אדם אחד ולנסות איתו אמת קטנה. הדלת נפתחת ממי שמדבר ראשון.");
RAKIA.TEXTS.aspect["venus-pluto"].square = T("ריבוע בין ונוס לפלוטו יוצר חיכוך בין רצון להתמסר לבין רצון לשלוט. הכוח הוא תשוקה ועומק, והאתגר הוא כוחניות שמסתירה פגיעות. למשל, ויכוח קטן על מי שוטף כלים הופך למאבק על מי יותר חשוב בקשר, ואיש לא זוכר את הכלים. מתחת למאבק יש פחד להיות פחות נאהב. עוזר לזכור שאהבה אינה מאבק, ולומר את הפחד במקום את הדרישה. מה שעוזר עוד הוא לעצור רגע ולשאול מה באמת רוצים. העומק כאן אמיתי, והוא נפתח כשהיד מרפה.");
RAKIA.TEXTS.aspect["venus-pluto"].trine = T("משולש בין ונוס לפלוטו מזרים עומק רגשי בטבעיות. קשרים כאן נוגעים בשכבות שמתחת, ואנשים נפתחים בקלות. למשל, בנסיעה ארוכה ברכבת אדם זר מספר למי שנושא את זה את סיפור חייו, ויורד בתחנה מרגיש קל יותר. הזרימה עלולה להירדם לעוצמה שאינה נבחנת, ולכן עוזר לשאול לפעמים לאן זה מוביל. הצד המאתגר הוא לשאת כל כך הרבה של אחרים בלי לשים לב למשקל. עוזר לבחור למי נותנים את העומק, ולשמור קצת גם לעצמו. הכוח הזה שקט, ולכן קל לשכוח כמה הוא גדול.");
RAKIA.TEXTS.aspect["venus-pluto"].opposition = T("ניגוד בין ונוס לפלוטו מותח בין נעימות לבין עוצמה. צד אחד רוצה שלום ורוגע בקשר, והצד השני מבקש אמת גם כשהיא קשה. למשל, בארוחה משפחתית מי שנושא את זה מחייך ומעביר את המלח, ובדרך הביתה במכונית פורצת שיחה על כל מה שלא נאמר בשולחן. הצד המאתגר הוא שהאמת יוצאת בבת אחת, אחרי שהנעימות החזיקה יותר מדי. האיזון נמצא כשלא מוותרים על אחד מהם. עוזר לומר דבר קטן ואמיתי מוקדם, לפני שהוא הופך לגדול. כך הרוגע הוא אמיתי ולא רק שקט.");

