RAKIA.TEXTS.aspect["uranus-pluto"].conjunction = T("צמידות בין אורנוס לפלוטו ממזגת מהפכה עם שינוי יסודי. הכוח הוא אומץ לשבור ולבנות מחדש, והאתגר הוא קיצוניות. למשל, כשמשהו בבית כבר לא עובד, מי שנושא את זה אינו מזיז רהיט אלא מפרק את כל החדר ובונה אותו אחרת, וזה יכול להיות נפלא או מתיש למי שגר שם. הצד השני הוא שהאומץ הזה מזיז דברים שנתקעו שנים. השילוב מלווה דור שלם, והבתים שבהם הוא יושב אומרים איפה הוא נוגע באופן אישי. עוזר לשאול לפני כל מהפכה אם צריך לשבור הכול, או רק חלק. הכוח לשנות אמיתי, ומידה עושה אותו נעים לחיות לידו.");
RAKIA.TEXTS.aspect["uranus-pluto"].sextile = T("שישית בין אורנוס לפלוטו מציעה הזדמנות לשינוי אמיתי בדרך חדשה. הפתח מבקש יוזמה ונכונות לשחרר. למשל, הרגל ישן של לומר כן לכל בקשה יכול להשתנות כאן, אם מתחילים מפעם אחת שאומרים לא בנעימות, ורואים שהעולם ממשיך. זהו אספקט של שנים ארוכות, ומה שהוא אומר על מפה אחת תלוי בבתים. הצד המאתגר הוא לחכות לרגע מתאים יותר, שאינו מגיע. עוזר לבחור דבר אחד ישן ולעזוב אותו בשקט, בלי הכרזות. מה שמשתחרר מפנה מקום.");
RAKIA.TEXTS.aspect["uranus-pluto"].square = T("ריבוע בין אורנוס לפלוטו יוצר חיכוך בין חופש לבין כוח. החיכוך מניע לפרוץ מסגרות, אך גם מייצר מאבק. למשל, בוועד הבית מי שנושא את זה נלחם על עיקרון עד שכולם עייפים, ולמחרת מגלה שהעיקרון היה נכון אך איש אינו רוצה לשמוע. הצד השני הוא שבלי אנשים כאלה שום דבר ישן אינו משתנה. משותף לבני אותה תקופה, ולכן הבתים במפה הם שמספרים איפה הוא מורגש בחיים של כל אחד. עוזר לשאול באמצע המאבק אם המטרה היא שינוי או ניצחון. הכוח הזה מזיז, וטוב לו כשהוא גם מקשיב.");
RAKIA.TEXTS.aspect["uranus-pluto"].trine = T("משולש בין אורנוס לפלוטו מזרים יכולת להשתנות בלי לאבד יציבות. למשל, אחרי מעבר לעיר חדשה מי שנושא את זה מוצא תוך חודש חברים, מסלול הליכה ובית קפה קבוע, כאילו גר שם שנים. הזרימה עלולה להירדם לביטחון שאינו נבחן, שבו נדמה שכל שינוי הולך בקלות ולכן לא מתכוננים. רבים חולקים אותו, כי הפלנטות איטיות, והבתים לבדם הופכים אותו לאישי. הצד המאתגר הוא לשכוח שאחרים אינם מסתגלים באותה מהירות, ולהיות קצר רוח כלפיהם. עוזר לחכות לאחרים ולתת להם זמן. הגמישות הזאת מתנה, וטוב לה כשהיא סבלנית.");
RAKIA.TEXTS.aspect["uranus-pluto"].opposition = T("ניגוד בין אורנוס לפלוטו מותח בין רצון לפרוץ לבין רצון לשלוט. למשל, מי שנושא את זה מבקש חופש מוחלט בתוכניות המשפחה, ובאותו רגע רוצה שכולם יעשו בדיוק מה שהוא אומר, ואינו רואה את הסתירה. הצד המאתגר הוא שמי שסביב מרגיש שהכללים משתנים לפי מצב הרוח. האיזון נמצא כשהחופש מכבד גבול והכוח מרפה. האספקט חוזר אצל דור שלם, והבתים נותנים לו פנים אישיות. עוזר לשאול לפני כל דרישה אם גם האחר מקבל את החופש הזה. כך שני הצדדים חיים באותו בית בשלום.");

RAKIA.TEXTS.aspect["neptune-pluto"] = RAKIA.TEXTS.aspect["neptune-pluto"] || {};
RAKIA.TEXTS.aspect["neptune-pluto"].conjunction = T("כשנפטון ופלוטו בצמידות, חלום ועומק נמזגים לרוח של דורות. יש כאן חיפוש משמעות מתחת לפני השטח, אך גם ערפל. למשל, מי שנושא את זה יכול לשבת בשיחה קלה על מזג האוויר ולשאול פתאום למה בעצם אנחנו כאן, ואנשים או נפתחים או מתבלבלים. הצד המאתגר הוא לחפש עומק בכל דבר ולפספס את הפשוט. השילוב נמשך שנים רבות מאוד, והבתים במפה הם שנותנים לו משמעות אצל אדם אחד. עוזר לתת גם לשיחה קלה להיות רק קלה, ולשמור את העומק לרגע שמבקש אותו. החיפוש הזה יפה, וטוב לו כשיש בו גם מנוחה.");
RAKIA.TEXTS.aspect["neptune-pluto"].sextile = T("שישית בין נפטון לפלוטו פותחת הזדמנות לשינוי פנימי דרך דמיון ואמונה. ההזדמנות מבקשת מי שיוזם. למשל, הרגל של הליכה שקטה בערב, בלי טלפון, יכול להפוך כאן לזמן שבו דברים ישנים מסתדרים מבפנים, אם מתמידים בו. הוא משותף לרבים מאוד, כי הפלנטות איטיות ביותר, ומה שאישי בו נקרא מהבתים. הצד המאתגר הוא להרגיש שמשהו רוצה להשתנות ולא לתת לו זמן ומקום. עוזר לקבוע רבע שעה ביום שאין בה שום משימה. מה שצומח בשקט צומח עמוק.");
RAKIA.TEXTS.aspect["neptune-pluto"].square = T("ריבוע בין נפטון לפלוטו מפגיש חלום עם כוח. החיכוך מניע לחפש אמת, אך גם מייצר חשד ובלבול. למשל, מי שנושא את זה יכול לשמוע סיפור פשוט של חבר ולחפש בו כוונה נסתרת, ולפעמים למצוא כזאת ולפעמים להמציא אותה. הצד השני הוא שהחיפוש הזה רואה לפעמים מה שאחרים מעדיפים לא לראות. האספקט מלווה תקופה ארוכה, והבתים לבדם מספרים איפה הוא נוגע בחיים הפרטיים. עוזר לשאול שאלה ישירה במקום להסיק בשקט, ולתת לתשובה הפשוטה להיות נכונה. כך האמת נמצאת בלי לאבד את האמון.");
RAKIA.TEXTS.aspect["neptune-pluto"].trine = T("משולש בין נפטון לפלוטו מזרים אינטואיציה עמוקה ויכולת להתחדש מבפנים. למשל, אחרי תקופה קשה מי שנושא את זה חוזר לעצמו בשקט, בלי הכרזות, ואנשים סביב שמים לב רק כשהוא כבר צוחק שוב. הזרימה עלולה להירדם לפסיביות, שבה מחכים שהדברים יסתדרו מעצמם כי הם הסתדרו בעבר. משותף לדורות שלמים, ולכן הבתים במפה הם שקובעים מה הוא אומר בפועל. הצד המאתגר הוא לסמוך על התחושה ולא לפעול לפיה. עוזר לתת לתחושה מעשה אחד קטן, כמו שיחה או צעד. הכוח הזה שקט, וכשהוא זז הוא מגיע רחוק.");
RAKIA.TEXTS.aspect["neptune-pluto"].opposition = T("ניגוד בין נפטון לפלוטו מותח בין התמסרות לבין שליטה. למשל, מי שנושא את זה יכול להתמסר לגמרי לחבר, למטרה או לרעיון, ובאותו זמן לרצות לדעת בדיוק לאן זה הולך ולהחזיק את החבל ביד. הצד המאתגר הוא שהאחיזה מקלקלת את ההתמסרות, וההתמסרות מפחידה את היד שאוחזת. האיזון הוא לשחרר בלי לאבד עומק, ולהחזיק בלי לחנוק. זו חתימה של דורות רבים, והבתים במפה מקרבים אותה אל האישי. עוזר לשאול מה באמת בשליטה ומה לא, ולתת לשאר ללכת. כך העומק נשאר, והיד נחה.");

/* ארבעת היסודות — מה זה אומר כשיסוד בולט במפה */
RAKIA.TEXTS.element.fire = T("כשיסוד האש בולט במפה, יש הרבה תנועה ורצון. האנרגיה הזאת מתחילה דברים, מתלהבת ומובילה, ומחממת את מי שסביב. למשל, בטיול משפחתי מי שנושא את זה הוא מי שקם ראשון, מציע את המסלול, וכבר הולך לפני שכולם נעלו נעליים, ובערב הוא שנרדם ראשון על הספה. האתגר הוא קוצר רוח ושריפה מהירה של כוחות, ולפעמים גם מילה חדה שיוצאת לפני שחשבו עליה. הצד השני הוא שבלי האש הזאת הרבה דברים לא היו מתחילים בכלל. מה שעוזר הוא לבחור מטרה אחת ולתת לה זמן, ולזכור שגם מנוחה היא חלק מהדרך. החום הזה יקר, וכשהוא נשמר הוא מחמם הרבה זמן.");
RAKIA.TEXTS.element.earth = T("יסוד האדמה בולט במפה מספר על יציבות ומעשה. הנטייה כאן היא לבנות לאט, לבדוק מה עובד ולהחזיק במה שנבנה. למשל, כשכולם בעבודה מתלהבים משיטה חדשה, מי שנושא את זה שואל בשקט מה היה בעייתי בישנה, ורק אחרי תשובה טובה עובר, ואז נשאר לאורך זמן. הצד השני הוא קושי לזוז כשצריך שינוי, והיצמדות למוכר גם כשהוא כבר לא משרת. יש כאן גם נוחות פשוטה, אוכל טוב, בית מסודר, ידיים שיודעות לתקן. עוזר להזמין מדי פעם משהו לא מתוכנן, כמו דרך אחרת הביתה או מאכל שלא טעמו. היציבות הזאת נותנת לאחרים מקום לנוח, וגם היא צריכה לפעמים רוח.");
RAKIA.TEXTS.element.air = T("יש כאן יסוד אוויר בולט, ומשמעותו מחשבה וקשר. האנרגיה הזאת אוהבת רעיונות, שיחה, שאלות וחיבור בין אנשים. למשל, בארוחת ערב עם חברים מי שנושא את זה פותח נושא, מחבר בין שני אנשים שלא הכירו, ומגלה בסוף שהוא לא סיים לאכול. האתגר הוא להישאר בראש ולהתרחק מהרגש ומהגוף, ולדבר על תחושה במקום להרגיש אותה. הצד השני הוא שהראש הזה רואה קשרים שאחרים מפספסים, ומקל על כולם להבין זה את זה. מה שמאזן הוא לתת גם לתחושה מקום ליד השולחן, ולפעמים לשתוק דקה. הקלילות הזאת מתנה, ועומק רגשי עושה אותה שלמה.");
RAKIA.TEXTS.element.water = T("מי שנושא יסוד מים בולט במפה חי דרך רגש והקשבה. הנטייה היא לחוש את החדר לפני שמישהו מדבר, ולהבין בלי מילים. למשל, בישיבת צוות מתוחה מי שנושא את זה מרגיש את המתח עוד לפני שמישהו אמר משהו, ובדרך הביתה נושא אותו איתו כאילו היה שלו. הצד המאתגר הוא הצפה, לקיחת רגשות של אחרים והתכנסות, עד שקשה להבחין מה מבפנים ומה מבחוץ. הצד השני הוא שאנשים באים לכאן כשקשה להם, כי כאן מקשיבים באמת. מה שעוזר הוא גבול רך: להרגיש, ולהחליט מה שייך ומה לא. הרגישות הזאת נדירה, וטוב לה כשהיא שומרת גם על עצמה.");
